    Mockito.when(migrationRule.getThreshold(Mockito.any())).thenReturn(1.0f);
    migrationInvoker.migrateToForceApplicationInvoker(migrationRule);
    migrationInvoker.setMigrationStep(MigrationStep.FORCE_APPLICATION);
